import{_ as a,C as s,o as r,c as o,E as d,a3 as i}from"./chunks/framework.CnxW2X0z.js";const n="/versions/v0.19.93/screens/devices/m2cv.png",l="/versions/v0.19.93/screens/devices/m2cv-gate.png",y=JSON.parse('{"title":"M2CV","description":"","frontmatter":{"title":"M2CV","pageClass":"device-doc"},"headers":[],"relativePath":"devices/m2cv.md","filePath":"devices/m2cv.md"}'),h={name:"devices/m2cv.md"};function c(g,t,p,m,u,v){const e=s("DeviceHeading");return r(),o("div",null,[d(e,{slug:"m2cv",title:"M2CV"}),t[0]||(t[0]=i('<p>MIDI to control voltage</p><p><img src="'+n+'" alt="M2CV parameters" class="screen"></p><p>The right side shows the 16 CV outputs as they sit on the CV16 panel: CV1 top left, numbered down each column, CV16 bottom right. Each output shows what it carries in this <strong>Mode</strong>. In <strong>AUTO</strong> and <strong>CHANNEL</strong>, each column is one voice: <strong>P1</strong> pitch, <strong>G1</strong> gate, <strong>V1</strong> velocity, and <strong>--</strong> unused. In <strong>GATE</strong>, each output shows the note that opens its gate. CV16 is always the clock (<strong>CLK</strong>). Outputs that are high right now are White.</p><p><img src="'+l+'" alt="M2CV in GATE mode" class="screen"></p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Convert MIDI notes or gates to <strong>control voltages</strong> with optional voice-allocation rules.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use <strong>M2CV</strong> at the <strong>end</strong> of a CV16-equipped rig.</p></div><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><div class="device-params-table"><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>BYPASS</td><td>0 – 1</td><td>When on, the device is disabled and MIDI passes through unchanged.</td></tr><tr><td>MODE</td><td>0 – 2</td><td>Operating mode for this device (see values below).</td></tr><tr><td>ALGO</td><td>0 – 6</td><td>Voice-allocation or routing algorithm (see values below).</td></tr></tbody></table></div><h2 id="parameter-values" tabindex="-1">Parameter values <a class="header-anchor" href="#parameter-values" aria-label="Permalink to &quot;Parameter values&quot;">​</a></h2><h3 id="bypass" tabindex="-1">Bypass <a class="header-anchor" href="#bypass" aria-label="Permalink to &quot;Bypass&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>OFF</td><td>Device is active and processes MIDI.</td></tr><tr><td style="text-align:right;">1</td><td>ON</td><td>Device is bypassed; messages pass through unchanged.</td></tr></tbody></table><h3 id="mode" tabindex="-1">Mode <a class="header-anchor" href="#mode" aria-label="Permalink to &quot;Mode&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>Auto</td><td>M2CV: map notes to CV automatically by pitch.</td></tr><tr><td style="text-align:right;">1</td><td>Channel</td><td>M2CV: one CV channel per MIDI channel.</td></tr><tr><td style="text-align:right;">2</td><td>Gate</td><td>M2CV: emit gate/trigger voltages from note on/off.</td></tr></tbody></table><h3 id="algo" tabindex="-1">Algo <a class="header-anchor" href="#algo" aria-label="Permalink to &quot;Algo&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>None</td><td>No voice stealing — one voice per note.</td></tr><tr><td style="text-align:right;">1</td><td>Oldest</td><td>Steal the longest-held voice when poly limit reached.</td></tr><tr><td style="text-align:right;">2</td><td>Newest</td><td>Replace the most recent voice.</td></tr><tr><td style="text-align:right;">3</td><td>Lowest</td><td>Steal the lowest-pitched active voice.</td></tr><tr><td style="text-align:right;">4</td><td>Highest</td><td>Steal the highest-pitched active voice.</td></tr><tr><td style="text-align:right;">5</td><td>Low Vel</td><td>Steal the quietest active voice.</td></tr><tr><td style="text-align:right;">6</td><td>High Vel</td><td>Steal the loudest active voice.</td></tr></tbody></table>',16))])}const x=a(h,[["render",c]]);export{y as __pageData,x as default};
